// Single source of truth for the security headers applied to responses that
// Cloudflare routes through THIS Worker: admin HTML, /api/admin/*, and
// /api/public/*.
//
// Cloudflare does NOT apply public/_headers rules to responses produced by
// Worker code. Verbatim from
// https://developers.cloudflare.com/workers/static-assets/headers/ :
// "Custom headers defined in the `_headers` file are not applied to
// responses generated by your Worker code, even if the request URL matches
// a rule defined in `_headers`." The same page says that with
// `run_worker_first` (or any SSR framework / other Worker script in front of
// assets), custom headers must be attached directly in the Worker script
// instead. That includes a response this Worker gets by calling
// `env.ASSETS.fetch()` and then returns itself, as worker.js's own admin
// routes do -- once this Worker's `fetch` handler is what produces the final
// Response, `_headers` no longer applies to it.
//
// wrangler.jsonc's `assets.run_worker_first` lists '/admin', '/admin/*', and
// '/api/*', so every one of those paths is always answered by this Worker --
// `public/_headers`' own `/admin/*` and `/*` blocks are therefore DEAD for
// those paths in production; they only still apply to the rest of the static
// site (anything not matched by run_worker_first). That's why admin HTML,
// /api/admin/*, and /api/public/* must set these headers here, explicitly, on
// every response this module's helpers are applied to.
//
// tests/csp-header.test.js imports CSP from here so public/_headers' own
// `/*` line is asserted equal to this constant -- the two can never drift
// apart silently.
export const CSP = "default-src 'self'; script-src 'self' https://challenges.cloudflare.com; " +
  "style-src 'self' 'unsafe-inline'; frame-src https://challenges.cloudflare.com; " +
  "connect-src 'self'; img-src 'self' data:; form-action 'self'; base-uri 'self'; " +
  "object-src 'none'; frame-ancestors 'none'"

const BASE = {
  'Content-Security-Policy': CSP,
  'X-Frame-Options': 'DENY',
  'X-Content-Type-Options': 'nosniff',
  'Referrer-Policy': 'strict-origin-when-cross-origin',
}

// Admin HTML (the two c.env.ASSETS.fetch admin routes in worker.js) and
// /api/admin/* JSON: the base set, plus no-store caching and a noindex
// signal -- admin surfaces must never be cached by a shared/browser cache
// nor indexed, the same promise public/_headers' (dead, for these paths)
// `/admin/*` block makes for the rest of the site.
export const ADMIN_HEADERS = {
  ...BASE,
  'Cache-Control': 'no-store',
  'X-Robots-Tag': 'noindex, nofollow',
}

// /api/public/* JSON: CSP/X-Frame-Options/X-Content-Type-Options/Referrer-Policy
// only. No Cache-Control/X-Robots-Tag override here -- public-site.js sets
// its own deliberate Cache-Control, and public API JSON carries no
// indexing concern the rest of the public site doesn't already have.
export const PUBLIC_API_HEADERS = BASE

/**
 * Return a clone of `res` with `headers` merged in (each one overwriting any
 * existing header of the same name; everything else on `res` -- status,
 * statusText, body -- is preserved). A Workers/Fetch `Response`'s `headers`
 * are mutable via `.set()`, but `res` itself may be a response produced
 * upstream (e.g. by `env.ASSETS.fetch()`) that callers should treat as
 * immutable, so this always returns a new Response rather than mutating the
 * one passed in.
 */
export function withHeaders(res, headers) {
  const out = new Response(res.body, res)
  for (const [key, value] of Object.entries(headers)) out.headers.set(key, value)
  return out
}
